        }

        let message_id = sqs::new_identifier();
        // Only a FIFO queue sequences its messages; `SequenceNumber` "applies only to
        // FIFO (first-in-first-out) queues".
        let sequence_number = fifo.then(|| queue.next_sequence_number());
        // Who this message is FROM, read from the credential that signed this send: it is
        // recorded on the message, so what a consumer reads under `SenderId` is the sender
        // of the send that arrived.
        let sender_id = sqs::authorization::sender_id(&*self.engine, ctx);

        queue.messages.push_back(sqs::StoredMessage {
            message_id: message_id.clone(),
            body: input.message_body,
            md5_of_body: md5_of_body.clone(),
            message_attributes,
            message_system_attributes,
            message_group_id: group_id,
            message_deduplication_id: deduplication_id,
            sequence_number: sequence_number.clone(),
            sent_at: now,
            // The queue this send enqueues the message in is the one it was sent to, so
            // its retention runs from the same instant.
            retention_from: now,
            sender_id,
            available_at: sqs::after(now, delay),
            invisible_until: None,
            receive_count: 0,
            queue_receive_count: 0,
            first_received_at: None,
            last_received_at: None,
            // A send puts the message in this queue directly: no redrive moved it here,
            // so it names no dead-letter source.
            dead_letter_source_arn: None,
            // The data key the queue is sealing its messages under, for a queue on a
            // customer managed key; a queue on the Amazon SQS owned key needs none.
            data_key,
        });
        if let (Some(key), Some(sequence_number)) = (deduplication_key, sequence_number.clone()) {
            queue.record_deduplication(
                key,
                sqs::Deduplication {
                    message_id: message_id.clone(),
                    sequence_number,
                    accepted_at: now,
                },
            );
        }
        // One message was added to this queue, of the size Amazon SQS measures a message at:
        // what the `AWS/SQS` sent counters count (`sqs::QueueTraffic`).
        queue.count_sent(size, now);

        Ok(SendMessageOutput {
            md5_of_message_body: Some(md5_of_body),
            md5_of_message_attributes,
            md5_of_message_system_attributes,
            message_id: Some(message_id),
            sequence_number,
        })
    }
}

/// The KMS refusal of the queue's key, as this operation's own modelled error.
///
/// Each class answers with the code KMS answers it with — the `awsQueryError` codes the
/// model carries for these shapes (`KMS.NotFoundException`, `KMS.DisabledException`,
/// `KMS.InvalidStateException`, `KMS.InvalidKeyUsageException`,
/// `KMS.AccessDeniedException`) — carrying the message KMS words that refusal in.
fn kms_refusal(refusal: sqs::encryption::KeyRefusal) -> SendMessageError {
    use sqs::encryption::KeyRefusal;
    match refusal {
        KeyRefusal::NotFound(message) => SendMessageErrorModeled::KmsNotFound(KmsNotFound {
            message: Some(message),
        }),
        KeyRefusal::Disabled(message) => SendMessageErrorModeled::KmsDisabled(KmsDisabled {
            message: Some(message),
        }),
        KeyRefusal::InvalidState(message) => {
            SendMessageErrorModeled::KmsInvalidState(KmsInvalidState {
                message: Some(message),
            })
        }
        KeyRefusal::InvalidKeyUsage(message) => {
            SendMessageErrorModeled::KmsInvalidKeyUsage(KmsInvalidKeyUsage {
                message: Some(message),
            })
        }
        KeyRefusal::AccessDenied(message) => {
            SendMessageErrorModeled::KmsAccessDenied(KmsAccessDenied {
                message: Some(message),
            })
        }
    }
    .into()
}

